import type { GazeFrame, HudConfig, HudZone, ZoneId } from './contracts';

export interface DwellStepResult {
  activeZoneId: ZoneId | null;
  completedZoneId: ZoneId | null;
  progressByZone: Map<ZoneId, number>;
}

/**
 * Pure Leaky-Integrator Dwell Controller.
 *
 * Non-negotiable safety invariants:
 * - Inside active hitbox with confidence >= minConfidence: +dt / dwellMs
 * - Outside hitbox or confidence < minConfidence: -decayMultiplier * dt / dwellMs
 * - Clamped strictly to [0.0, 1.0]
 * - Never treats low-confidence frames as hits, preventing (0,0) face-loss false triggers.
 */
export class LeakyDwellController {
  private progress = new Map<ZoneId, number>();
  private lastTimestampMs: number | null = null;

  reset(): void {
    this.progress.clear();
    this.lastTimestampMs = null;
  }

  getProgress(zoneId: ZoneId): number {
    return this.progress.get(zoneId) ?? 0;
  }

  snapshot(): Map<ZoneId, number> {
    return new Map(this.progress);
  }

  step(frame: GazeFrame, zones: readonly HudZone[], config: HudConfig): DwellStepResult {
    const dtMs = this.computeDeltaMs(frame.timestamp);
    const hasConfidence =
      Number.isFinite(frame.x) &&
      Number.isFinite(frame.y) &&
      frame.confidence >= config.minConfidence;

    let activeZoneId: ZoneId | null = null;
    if (hasConfidence) {
      for (const zone of zones) {
        if (zone.disabled) continue;
        if (pointInRect(frame.x, frame.y, zone.rect)) {
          activeZoneId = zone.id;
          break;
        }
      }
    }

    let completedZoneId: ZoneId | null = null;

    for (const zone of zones) {
      if (zone.disabled || zone.dwellMs <= 0) {
        this.progress.set(zone.id, 0);
        continue;
      }

      const prev = this.progress.get(zone.id) ?? 0;
      const isHit = hasConfidence && zone.id === activeZoneId;
      const delta = isHit
        ? dtMs / zone.dwellMs
        : (-config.decayMultiplier * dtMs) / zone.dwellMs;

      const next = Math.max(0, Math.min(1, prev + delta));
      this.progress.set(zone.id, next);

      if (next >= 1 && completedZoneId === null) {
        completedZoneId = zone.id;
      }
    }

    // Prune stale progress entries not in current zone set.
    const currentIds = new Set(zones.map((z) => z.id));
    for (const existingId of this.progress.keys()) {
      if (!currentIds.has(existingId)) {
        this.progress.delete(existingId);
      }
    }

    return {
      activeZoneId,
      completedZoneId,
      progressByZone: new Map(this.progress),
    };
  }

  private computeDeltaMs(timestampMs: number): number {
    if (this.lastTimestampMs === null || timestampMs <= this.lastTimestampMs) {
      this.lastTimestampMs = timestampMs;
      return 0;
    }
    // Cap dt at 100ms so background tab throttling cannot jump dwell to 100%.
    const dt = Math.min(100, timestampMs - this.lastTimestampMs);
    this.lastTimestampMs = timestampMs;
    return dt;
  }
}

export function pointInRect(
  x: number,
  y: number,
  rect: { x0: number; y0: number; x1: number; y1: number },
): boolean {
  return x >= rect.x0 && x <= rect.x1 && y >= rect.y0 && y <= rect.y1;
}
