import {
  TrackerState,
  WebcamETLight,
  type CalibrationSample,
} from '@realeye-io/webcam-eyetracker-light-open';
import type { GazeFrame, GazeProvider } from './contracts';
import { clamp01 } from './OneEuroFilter';

export interface RealEyeProviderOptions {
  attemptId: string;
  /** Optional base URL pointing to Moodle plugin assets/ directory (local -> CDN fallback). */
  localAssetBaseUrl?: string;
  onCalibrationComplete?: () => void;
  onErrorModal?: (title: string, detail: string) => void;
}

interface StoredCalibration {
  coefficientsX: number[];
  coefficientsY: number[];
  viewportWidth: number;
  viewportHeight: number;
  savedAt: number;
}

const CALIBRATION_GRID_3X3: ReadonlyArray<{ x: number; y: number }> = [
  { x: 0.1, y: 0.1 },
  { x: 0.5, y: 0.1 },
  { x: 0.9, y: 0.1 },
  { x: 0.1, y: 0.5 },
  { x: 0.5, y: 0.5 },
  { x: 0.9, y: 0.5 },
  { x: 0.1, y: 0.9 },
  { x: 0.5, y: 0.9 },
  { x: 0.9, y: 0.9 },
];

const SETTLE_MS = 400;
const SAMPLES_PER_POINT = 5;
const SAMPLE_INTERVAL_MS = 200;

/**
 * Wraps @realeye-io/webcam-eyetracker-light-open into Gaze-CBT's normalized GazeFrame contract:
 * - Pre-Flight webcam check (640x480 @ 30fps, GPU -> CPU WASM fallback)
 * - 9-point hands-free passive timed calibration (3x3)
 * - sessionStorage Ridge weights restore across Moodle page reloads
 * - Face-Loss Sanitization (never defaults to (0,0); preserves last valid point with confidence=0)
 */
export class RealEyeGazeProvider implements GazeProvider {
  readonly kind = 'webcam' as const;
  private tracker: WebcamETLight | null = null;
  private stream: MediaStream | null = null;
  private videoEl: HTMLVideoElement | null = null;
  private overlayEl: HTMLElement | null = null;
  private rafId: number | null = null;
  private lastPredictAt = 0;

  // Holds last valid normalized coordinate; never resets to (0,0) inside PREV hitbox.
  private lastValidX = 0.5;
  private lastValidY = 0.5;

  constructor(
    private readonly options: RealEyeProviderOptions,
    private readonly doc: Document = document,
  ) {}

  async start(onFrame: (frame: GazeFrame) => void): Promise<void> {
    try {
      await this.initCamera();
      await this.initTrackerWithFallback();

      const restored = this.tryRestoreCalibration();
      if (!restored) {
        await this.runHandsFree9PointCalibration();
      }

      this.options.onCalibrationComplete?.();
      this.startPredictionLoop(onFrame);
    } catch (err) {
      const { title, detail } = classifyHardwareError(err);
      this.showDiagnosticModal(title, detail);
      this.options.onErrorModal?.(title, detail);
      throw err;
    }
  }

  stop(): void {
    if (this.rafId !== null) {
      window.cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.overlayEl?.remove();
    this.overlayEl = null;
    this.videoEl?.remove();
    this.videoEl = null;
    if (this.stream) {
      for (const track of this.stream.getTracks()) {
        track.stop();
      }
      this.stream = null;
    }
    this.tracker?.dispose();
    this.tracker = null;
  }

  clearStoredCalibration(): void {
    try {
      sessionStorage.removeItem(this.storageKey());
    } catch {
      // Ignore storage failures.
    }
  }

  private storageKey(): string {
    return `gaze_cbt_cal_${this.options.attemptId}`;
  }

  private async initCamera(): Promise<void> {
    if (!navigator.mediaDevices?.getUserMedia) {
      throw new Error('NotSupportedError: WebRTC getUserMedia is unavailable in this browser.');
    }

    this.stream = await navigator.mediaDevices.getUserMedia({
      video: {
        width: { ideal: 640 },
        height: { ideal: 480 },
        frameRate: { ideal: 30 },
        facingMode: 'user',
      },
      audio: false,
    });

    const video = this.doc.createElement('video');
    video.playsInline = true;
    video.muted = true;
    video.autoplay = true;
    video.srcObject = this.stream;
    video.style.cssText = 'position:fixed;width:1px;height:1px;opacity:0;pointer-events:none;';
    this.doc.body.appendChild(video);
    await video.play();
    this.videoEl = video;
  }

  private async initTrackerWithFallback(): Promise<void> {
    const assetConfig = await this.resolveAssetPaths();
    try {
      this.tracker = new WebcamETLight({
        ...assetConfig,
        faceDetectorMode: 'landmarker',
        delegate: 'GPU',
        runningMode: 'VIDEO',
        minDetectionConfidence: 0.5,
      });
      await this.tracker.initialize();
    } catch {
      this.tracker?.dispose();
      this.tracker = new WebcamETLight({
        ...assetConfig,
        faceDetectorMode: 'landmarker',
        delegate: 'CPU',
        runningMode: 'VIDEO',
        minDetectionConfidence: 0.5,
      });
      await this.tracker.initialize();
    }
  }

  private async resolveAssetPaths(): Promise<{ modelPath?: string; wasmPath?: string }> {
    const base = this.options.localAssetBaseUrl?.replace(/\/$/, '');
    if (!base) return {};

    try {
      const modelUrl = `${base}/face_landmarker.task`;
      const probe = await fetch(modelUrl, { method: 'HEAD' });
      if (probe.ok) {
        return {
          modelPath: modelUrl,
          wasmPath: `${base}/wasm`,
        };
      }
    } catch {
      // Fallback transparently to default MediaPipe CDN URLs.
    }
    return {};
  }

  private tryRestoreCalibration(): boolean {
    if (!this.tracker) return false;
    try {
      const raw = sessionStorage.getItem(this.storageKey());
      if (!raw) return false;
      const saved = JSON.parse(raw) as StoredCalibration;
      if (
        !Array.isArray(saved.coefficientsX) ||
        !Array.isArray(saved.coefficientsY) ||
        saved.coefficientsX.length === 0
      ) {
        return false;
      }

      const internal = this.tracker as unknown as {
        coefficientsX: number[] | null;
        coefficientsY: number[] | null;
        state: TrackerState;
      };
      internal.coefficientsX = saved.coefficientsX;
      internal.coefficientsY = saved.coefficientsY;
      internal.state = TrackerState.Calibrated;
      return true;
    } catch {
      return false;
    }
  }

  private saveCalibrationToSession(): void {
    if (!this.tracker) return;
    const internal = this.tracker as unknown as {
      coefficientsX: number[] | null;
      coefficientsY: number[] | null;
    };
    if (!internal.coefficientsX || !internal.coefficientsY) return;

    const payload: StoredCalibration = {
      coefficientsX: internal.coefficientsX,
      coefficientsY: internal.coefficientsY,
      viewportWidth: window.innerWidth,
      viewportHeight: window.innerHeight,
      savedAt: Date.now(),
    };
    try {
      sessionStorage.setItem(this.storageKey(), JSON.stringify(payload));
    } catch {
      // Ignore storage failures.
    }
  }

  private async runHandsFree9PointCalibration(): Promise<void> {
    if (!this.tracker || !this.videoEl) {
      throw new Error('Tracker not initialized before calibration.');
    }

    const overlay = this.doc.createElement('div');
    overlay.id = 'gaze-cbt-calibration-overlay';
    overlay.style.cssText = [
      'position:fixed',
      'inset:0',
      'z-index:99995',
      'background:rgba(15,23,42,0.96)',
      'color:#f8fafc',
      'display:flex',
      'flex-direction:column',
      'align-items:center',
      'justify-content:center',
      'font-family:system-ui,-apple-system,sans-serif',
    ].join(';');

    const title = this.doc.createElement('div');
    title.style.cssText = 'font-size:22px;font-weight:700;margin-bottom:8px;text-align:center;';
    title.textContent = 'Kalibrasi Mata Hands-Free (9 Titik)';

    const subtitle = this.doc.createElement('div');
    subtitle.style.cssText = 'font-size:15px;color:#cbd5e1;text-align:center;max-width:480px;';
    subtitle.textContent = 'Ikuti lingkaran biru dengan mata Anda tanpa mengklik mouse.';

    const dot = this.doc.createElement('div');
    dot.style.cssText = [
      'position:fixed',
      'width:44px',
      'height:44px',
      'border-radius:999px',
      'background:#2563eb',
      'border:4px solid #93c5fd',
      'box-shadow:0 0 24px rgba(59,130,246,0.75)',
      'transform:translate(-50%,-50%)',
      'transition:left 220ms ease, top 220ms ease, transform 180ms ease',
    ].join(';');

    overlay.appendChild(title);
    overlay.appendChild(subtitle);
    overlay.appendChild(dot);
    this.doc.body.appendChild(overlay);
    this.overlayEl = overlay;

    const captureCanvas = this.doc.createElement('canvas');
    const captureCtx = captureCanvas.getContext('2d');
    if (!captureCtx) {
      throw new Error('Failed to create capture canvas for calibration.');
    }

    const samples: CalibrationSample[] = [];

    try {
      for (let idx = 0; idx < CALIBRATION_GRID_3X3.length; idx++) {
        const pt = CALIBRATION_GRID_3X3[idx];
        if (!pt) continue;

        dot.style.left = `${pt.x * 100}%`;
        dot.style.top = `${pt.y * 100}%`;
        dot.style.transform = 'translate(-50%,-50%) scale(1.15)';
        subtitle.textContent = `Titik ${idx + 1} dari ${CALIBRATION_GRID_3X3.length} — Tatap lingkaran biru`;

        await sleep(SETTLE_MS);
        dot.style.transform = 'translate(-50%,-50%) scale(0.9)';

        const gazeX = pt.x * window.innerWidth;
        const gazeY = pt.y * window.innerHeight;

        for (let s = 0; s < SAMPLES_PER_POINT; s++) {
          const vw = this.videoEl.videoWidth || 640;
          const vh = this.videoEl.videoHeight || 480;
          captureCanvas.width = vw;
          captureCanvas.height = vh;
          captureCtx.drawImage(this.videoEl, 0, 0, vw, vh);
          const image = captureCtx.getImageData(0, 0, vw, vh);
          samples.push({ image, gazeX, gazeY });
          if (s < SAMPLES_PER_POINT - 1) {
            await sleep(SAMPLE_INTERVAL_MS);
          }
        }
      }

      subtitle.textContent = 'Menghitung model kalibrasi pribadi...';
      this.tracker.calibrate(samples);
      this.saveCalibrationToSession();
    } finally {
      overlay.remove();
      this.overlayEl = null;
    }
  }

  private startPredictionLoop(onFrame: (frame: GazeFrame) => void): void {
    const loop = (now: number) => {
      if (!this.tracker || !this.videoEl) return;

      // Target ~30 FPS inference cadence.
      if (now - this.lastPredictAt >= 32 && this.videoEl.readyState >= 2) {
        this.lastPredictAt = now;
        try {
          const point = this.tracker.predict(this.videoEl);
          if (point && Number.isFinite(point.x) && Number.isFinite(point.y)) {
            const normX = clamp01(point.x / Math.max(1, window.innerWidth));
            const normY = clamp01(point.y / Math.max(1, window.innerHeight));
            this.lastValidX = normX;
            this.lastValidY = normY;
            onFrame({
              x: normX,
              y: normY,
              confidence: 1.0,
              timestamp: now,
            });
          } else {
            onFrame({
              x: this.lastValidX,
              y: this.lastValidY,
              confidence: 0.0,
              timestamp: now,
            });
          }
        } catch {
          onFrame({
            x: this.lastValidX,
            y: this.lastValidY,
            confidence: 0.0,
            timestamp: now,
          });
        }
      }
      this.rafId = window.requestAnimationFrame(loop);
    };
    this.rafId = window.requestAnimationFrame(loop);
  }

  private showDiagnosticModal(title: string, detail: string): void {
    const modal = this.doc.createElement('div');
    modal.id = 'gaze-cbt-preflight-error';
    modal.style.cssText = [
      'position:fixed',
      'inset:0',
      'z-index:99998',
      'background:rgba(15,23,42,0.92)',
      'display:flex',
      'align-items:center',
      'justify-content:center',
      'padding:24px',
      'font-family:system-ui,sans-serif',
    ].join(';');

    modal.innerHTML = `
      <div style="max-width:520px;background:#1e293b;color:#f8fafc;border:2px solid #f87171;border-radius:16px;padding:24px;">
        <h2 style="margin:0 0 12px;color:#fca5a5;font-size:20px;">${escapeHtml(title)}</h2>
        <p style="margin:0 0 16px;color:#cbd5e1;line-height:1.5;">${escapeHtml(detail)}</p>
        <p style="margin:0;color:#94a3b8;font-size:13px;">Hubungi proktor lab untuk memeriksa izin kamera SEB (<code>allowVideoCapture = true</code>) atau koneksi webcam.</p>
      </div>
    `;
    this.doc.body?.appendChild(modal);
  }
}

function classifyHardwareError(err: unknown): { title: string; detail: string } {
  const name = err instanceof Error ? err.name : '';
  const msg = err instanceof Error ? err.message : String(err);
  if (name === 'NotAllowedError' || /NotAllowedError/i.test(msg)) {
    return {
      title: 'Izin Kamera Diblokir (NotAllowedError)',
      detail: 'Browser atau Safe Exam Browser menolak akses webcam. Pastikan profil .seb mengaktifkan allowVideoCapture = true dan AllowFromOrigin.',
    };
  }
  if (name === 'NotFoundError' || /NotFoundError/i.test(msg)) {
    return {
      title: 'Webcam Tidak Ditemukan (NotFoundError)',
      detail: 'Tidak ada perangkat kamera yang terdeteksi pada komputer ini.',
    };
  }
  if (name === 'NotReadableError' || /NotReadableError/i.test(msg)) {
    return {
      title: 'Kamera Sedang Dipakai Aplikasi Lain (NotReadableError)',
      detail: 'Webcam terkunci oleh aplikasi lain. Tutup aplikasi video conference sebelum memulai ujian.',
    };
  }
  return {
    title: 'Gagal Memulai Eye-Tracker',
    detail: msg || 'Terjadi kesalahan saat inisialisasi MediaPipe Face Landmarker.',
  };
}

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');
}

function sleep(ms: number): Promise<void> {
  return new Promise((resolve) => window.setTimeout(resolve, ms));
}
