import type { HudZone } from './contracts';
import type { HudSnapshot } from './HudStateMachine';

const PALETTE = {
  backdrop: 'rgba(15, 23, 42, 0.85)',
  tileBg: 'rgba(30, 41, 59, 0.94)',
  tileOverlayBg: 'rgba(15, 23, 42, 0.92)',
  tileHoverBorder: '#60a5fa',
  tileDefaultBorder: 'rgba(148, 163, 184, 0.45)',
  blueFill: '#2563eb',
  amberBg: 'rgba(120, 53, 15, 0.92)',
  amberFill: '#d97706',
  amberBorder: '#fbbf24',
  dangerBg: 'rgba(69, 10, 10, 0.92)',
  dangerFill: '#dc2626',
  dangerBorder: '#f87171',
  confirmedBg: '#065f46',
  confirmedBorder: '#34d399',
  textPrimary: '#f8fafc',
  textSecondary: '#cbd5e1',
  pillBg: 'rgba(248, 250, 252, 0.96)',
  pillText: '#0f172a',
};

/**
 * Full-viewport HTML5 Canvas HUD renderer implementing unified left-to-right
 * clipped background dwell fills (drawFillButton).
 */
export class CanvasHudRenderer {
  private readonly canvas: HTMLCanvasElement;
  private readonly ctx: CanvasRenderingContext2D;
  private showGazeCursor = false;

  constructor(private readonly doc: Document = document) {
    this.canvas = this.doc.createElement('canvas');
    this.canvas.id = 'gaze-cbt-hud-canvas';
    this.canvas.style.position = 'fixed';
    this.canvas.style.inset = '0';
    this.canvas.style.width = '100vw';
    this.canvas.style.height = '100vh';
    this.canvas.style.pointerEvents = 'none';
    this.canvas.style.zIndex = '99990';

    const ctx = this.canvas.getContext('2d');
    if (!ctx) {
      throw new Error('Failed to initialize 2D context for Gaze-CBT Canvas HUD.');
    }
    this.ctx = ctx;
  }

  mount(): void {
    if (!this.canvas.isConnected && this.doc.body) {
      this.doc.body.appendChild(this.canvas);
    }
    this.resizeToViewport();
  }

  unmount(): void {
    this.canvas.remove();
  }

  setShowGazeCursor(visible: boolean): void {
    this.showGazeCursor = visible;
  }

  resizeToViewport(): { width: number; height: number } {
    const dpr = window.devicePixelRatio || 1;
    const width = window.innerWidth;
    const height = window.innerHeight;
    if (this.canvas.width !== Math.round(width * dpr) || this.canvas.height !== Math.round(height * dpr)) {
      this.canvas.width = Math.round(width * dpr);
      this.canvas.height = Math.round(height * dpr);
    }
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    return { width, height };
  }

  render(snapshot: HudSnapshot): void {
    const { width, height } = this.resizeToViewport();
    const ctx = this.ctx;
    ctx.clearRect(0, 0, width, height);

    if (snapshot.state === 'CALIBRATING') {
      return;
    }

    const isOverlay =
      snapshot.state === 'ANSWER_ENTRY_LOCK' ||
      snapshot.state === 'ANSWER_OVERLAY' ||
      snapshot.state === 'ACTION_COOLDOWN' ||
      snapshot.summaryModalOpen;

    if (isOverlay) {
      ctx.fillStyle = PALETTE.backdrop;
      ctx.fillRect(0, 0, width, height);
    }

    if (snapshot.state === 'READING' && !snapshot.summaryModalOpen) {
      this.drawStatusPill(snapshot, width, height);
    }

    for (const zone of snapshot.zones) {
      const progress = snapshot.progressByZone.get(zone.id) ?? 0;
      const isActive = snapshot.activeZoneId === zone.id;
      const isLockedOption =
        snapshot.state === 'ACTION_COOLDOWN' &&
        snapshot.lockedOptionIndex !== null &&
        zone.id === `OPT_${snapshot.lockedOptionIndex}`;

      this.drawFillButton(zone, progress, isActive, isLockedOption, width, height);
    }

    if (snapshot.state === 'ANSWER_ENTRY_LOCK') {
      this.drawTopBanner('Menstabilkan tatapan (500 ms)...', width, '#38bdf8');
    } else if (snapshot.faceLost) {
      this.drawTopBanner('Wajah tidak terdeteksi — posisikan wajah ke arah kamera', width, '#fbbf24');
    } else if (snapshot.multiQuestionWarning) {
      this.drawTopBanner('Peringatan: >1 soal per halaman terdeteksi; disarankan 1 soal/halaman', width, '#fbbf24');
    }

    if (this.showGazeCursor && snapshot.lastFrame && snapshot.lastFrame.confidence >= 0.5) {
      this.drawDebugReticle(snapshot.lastFrame.x * width, snapshot.lastFrame.y * height);
    }
  }

  /**
   * Unified clipped full-background left-to-right dwell fill button.
   */
  private drawFillButton(
    zone: HudZone,
    progress: number,
    isActive: boolean,
    isLockedConfirmed: boolean,
    vw: number,
    vh: number,
  ): void {
    const ctx = this.ctx;
    const x = zone.rect.x0 * vw + 6;
    const y = zone.rect.y0 * vh + 6;
    const w = (zone.rect.x1 - zone.rect.x0) * vw - 12;
    const h = (zone.rect.y1 - zone.rect.y0) * vh - 12;
    const radius = 14;

    let baseColor = zone.variant === 'option' ? PALETTE.tileOverlayBg : PALETTE.tileBg;
    let fillColor = PALETTE.blueFill;
    let borderColor = isActive ? PALETTE.tileHoverBorder : PALETTE.tileDefaultBorder;

    if (zone.variant === 'amber') {
      baseColor = PALETTE.amberBg;
      fillColor = PALETTE.amberFill;
      borderColor = PALETTE.amberBorder;
    } else if (zone.variant === 'danger') {
      baseColor = PALETTE.dangerBg;
      fillColor = PALETTE.dangerFill;
      borderColor = PALETTE.dangerBorder;
    }

    if (isLockedConfirmed) {
      baseColor = PALETTE.confirmedBg;
      borderColor = PALETTE.confirmedBorder;
    } else if (zone.checked && zone.variant === 'option') {
      borderColor = PALETTE.confirmedBorder;
    }

    ctx.save();
    traceRoundedRect(ctx, x, y, w, h, radius);
    ctx.fillStyle = baseColor;
    ctx.fill();

    // Clipped left-to-right solid fill sweep from 0.0 -> 1.0
    if (progress > 0 && !isLockedConfirmed) {
      ctx.save();
      traceRoundedRect(ctx, x, y, w, h, radius);
      ctx.clip();
      ctx.fillStyle = fillColor;
      ctx.fillRect(x, y, w * Math.max(0, Math.min(1, progress)), h);
      ctx.restore();
    }

    traceRoundedRect(ctx, x, y, w, h, radius);
    ctx.lineWidth = isActive || isLockedConfirmed || zone.checked ? 4 : 2;
    ctx.strokeStyle = borderColor;
    ctx.stroke();

    // Typography
    ctx.fillStyle = PALETTE.textPrimary;
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';

    if (zone.variant === 'option') {
      const letterSize = Math.max(36, Math.min(64, Math.round(h * 0.22)));
      const textSize = Math.max(18, Math.min(28, Math.round(h * 0.09)));

      ctx.font = `800 ${letterSize}px system-ui, -apple-system, sans-serif`;
      ctx.fillText(zone.label, x + w / 2, y + h * 0.34);

      if (zone.sublabel) {
        ctx.font = `500 ${textSize}px system-ui, -apple-system, sans-serif`;
        ctx.fillStyle = PALETTE.textSecondary;
        drawWrappedText(ctx, zone.sublabel, x + w / 2, y + h * 0.58, w - 48, textSize * 1.35, 3);
      }

      if (isLockedConfirmed || zone.checked) {
        const badgeText = isLockedConfirmed ? 'TERPILIH ✓' : 'SUDAH DIPILIH';
        ctx.font = '700 14px system-ui, -apple-system, sans-serif';
        ctx.fillStyle = PALETTE.confirmedBorder;
        ctx.fillText(badgeText, x + w / 2, y + h - 22);
      }
    } else {
      const labelSize = Math.max(24, Math.min(44, Math.round(h * 0.28)));
      ctx.font = `800 ${labelSize}px system-ui, -apple-system, sans-serif`;
      const centerY = zone.sublabel ? y + h * 0.42 : y + h / 2;
      ctx.fillText(zone.label, x + w / 2, centerY);

      if (zone.sublabel) {
        ctx.font = '500 16px system-ui, -apple-system, sans-serif';
        ctx.fillStyle = PALETTE.textSecondary;
        ctx.fillText(zone.sublabel, x + w / 2, y + h * 0.72);
      }
    }

    ctx.restore();
  }

  private drawStatusPill(snapshot: HudSnapshot, vw: number, vh: number): void {
    const ctx = this.ctx;
    const parts = [
      snapshot.navState.questionLabel,
      snapshot.navState.answeredLabel,
      snapshot.navState.timeLeftLabel,
    ].filter(Boolean);
    const label = parts.join('  •  ') || 'Gaze Focus Mode';

    const boxX = vw * 0.31;
    const boxW = vw * 0.38;
    const boxH = Math.min(54, vh * 0.08);
    const boxY = (vh * 0.22 - boxH) / 2;

    ctx.save();
    traceRoundedRect(ctx, boxX, boxY, boxW, boxH, 999);
    ctx.fillStyle = PALETTE.pillBg;
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = 'rgba(148, 163, 184, 0.5)';
    ctx.stroke();

    ctx.fillStyle = PALETTE.pillText;
    ctx.font = '700 16px system-ui, -apple-system, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(label, boxX + boxW / 2, boxY + boxH / 2, boxW - 28);
    ctx.restore();
  }

  private drawTopBanner(message: string, vw: number, accent: string): void {
    const ctx = this.ctx;
    const w = Math.min(560, vw * 0.6);
    const h = 36;
    const x = (vw - w) / 2;
    const y = 14;

    ctx.save();
    traceRoundedRect(ctx, x, y, w, h, 8);
    ctx.fillStyle = 'rgba(15, 23, 42, 0.95)';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = accent;
    ctx.stroke();

    ctx.fillStyle = PALETTE.textPrimary;
    ctx.font = '600 13px system-ui, -apple-system, sans-serif';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(message, vw / 2, y + h / 2, w - 24);
    ctx.restore();
  }

  private drawDebugReticle(px: number, py: number): void {
    const ctx = this.ctx;
    ctx.save();
    ctx.beginPath();
    ctx.arc(px, py, 10, 0, Math.PI * 2);
    ctx.fillStyle = 'rgba(56, 189, 248, 0.35)';
    ctx.fill();
    ctx.lineWidth = 2;
    ctx.strokeStyle = '#38bdf8';
    ctx.stroke();
    ctx.restore();
  }
}

function traceRoundedRect(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  w: number,
  h: number,
  r: number,
): void {
  const radius = Math.min(r, w / 2, h / 2);
  ctx.beginPath();
  ctx.moveTo(x + radius, y);
  ctx.arcTo(x + w, y, x + w, y + h, radius);
  ctx.arcTo(x + w, y + h, x, y + h, radius);
  ctx.arcTo(x, y + h, x, y, radius);
  ctx.arcTo(x, y, x + w, y, radius);
  ctx.closePath();
}

function drawWrappedText(
  ctx: CanvasRenderingContext2D,
  text: string,
  cx: number,
  startY: number,
  maxWidth: number,
  lineHeight: number,
  maxLines: number,
): void {
  const words = text.split(' ');
  const lines: string[] = [];
  let current = '';

  for (const word of words) {
    const candidate = current ? `${current} ${word}` : word;
    if (ctx.measureText(candidate).width <= maxWidth) {
      current = candidate;
    } else {
      if (current) lines.push(current);
      current = word;
      if (lines.length === maxLines - 1) break;
    }
  }
  if (current && lines.length < maxLines) {
    lines.push(current);
  }

  const totalHeight = (lines.length - 1) * lineHeight;
  lines.forEach((line, idx) => {
    ctx.fillText(line, cx, startY - totalHeight / 2 + idx * lineHeight, maxWidth);
  });
}
