/**
 * Adaptive 2D One-Euro Filter (Casiez et al., 2012) for normalized GazeFrame coordinates.
 * Smooths micro-jitter during fixation while preserving responsiveness on saccades.
 */

class LowPassFilter {
  private initialized = false;
  private y = 0;

  filter(value: number, alpha: number): number {
    if (!this.initialized) {
      this.initialized = true;
      this.y = value;
      return value;
    }
    this.y = alpha * value + (1 - alpha) * this.y;
    return this.y;
  }

  lastValue(): number {
    return this.y;
  }

  hasValue(): boolean {
    return this.initialized;
  }

  reset(): void {
    this.initialized = false;
    this.y = 0;
  }
}

class OneEuroAxis {
  private readonly xFilter = new LowPassFilter();
  private readonly dxFilter = new LowPassFilter();
  private lastTimestampMs: number | null = null;

  constructor(
    private readonly minCutoff: number,
    private readonly beta: number,
    private readonly dCutoff: number,
  ) {}

  private alpha(cutoffHz: number, dtSec: number): number {
    const tau = 1 / (2 * Math.PI * cutoffHz);
    return 1 / (1 + tau / dtSec);
  }

  filter(value: number, timestampMs: number): number {
    if (this.lastTimestampMs === null || timestampMs <= this.lastTimestampMs) {
      this.lastTimestampMs = timestampMs;
      this.dxFilter.filter(0, 1);
      return this.xFilter.filter(value, 1);
    }

    const dtSec = Math.max(1 / 120, Math.min(0.25, (timestampMs - this.lastTimestampMs) / 1000));
    this.lastTimestampMs = timestampMs;

    const prevX = this.xFilter.hasValue() ? this.xFilter.lastValue() : value;
    const dx = (value - prevX) / dtSec;
    const edx = this.dxFilter.filter(dx, this.alpha(this.dCutoff, dtSec));
    const cutoff = this.minCutoff + this.beta * Math.abs(edx);
    return this.xFilter.filter(value, this.alpha(cutoff, dtSec));
  }

  reset(): void {
    this.xFilter.reset();
    this.dxFilter.reset();
    this.lastTimestampMs = null;
  }
}

export class OneEuroFilter2D {
  private readonly xAxis: OneEuroAxis;
  private readonly yAxis: OneEuroAxis;

  constructor(minCutoff = 1.2, beta = 0.04, dCutoff = 1.0) {
    this.xAxis = new OneEuroAxis(minCutoff, beta, dCutoff);
    this.yAxis = new OneEuroAxis(minCutoff, beta, dCutoff);
  }

  /**
   * Filters a normalized [0, 1] coordinate pair.
   * Freezes filter history whenever confidence < minConfidence so face-loss never corrupts state.
   */
  filter(
    x: number,
    y: number,
    timestampMs: number,
    confidence: number,
    minConfidence: number,
  ): { x: number; y: number } {
    if (confidence < minConfidence || !Number.isFinite(x) || !Number.isFinite(y)) {
      return { x, y };
    }
    return {
      x: clamp01(this.xAxis.filter(clamp01(x), timestampMs)),
      y: clamp01(this.yAxis.filter(clamp01(y), timestampMs)),
    };
  }

  reset(): void {
    this.xAxis.reset();
    this.yAxis.reset();
  }
}

export function clamp01(value: number): number {
  if (!Number.isFinite(value)) return 0.5;
  return Math.max(0, Math.min(1, value));
}
