import {
  DEFAULT_HUD_CONFIG,
  type GazeFrame,
  type HudConfig,
  type HudState,
  type HudZone,
  type MoodleNavState,
  type MoodlePageKind,
  type QuestionOption,
  type ZoneId,
} from './contracts';
import {
  buildAnswerOverlayZones,
  buildReadingZones,
  buildSummaryModalZones,
  buildSummaryReadingZones,
} from './HitboxLayout';
import { LeakyDwellController } from './LeakyDwellController';
import type { MoodleDomBridge } from './MoodleDomBridge';
import { OneEuroFilter2D } from './OneEuroFilter';
import type { BenchmarkLogger } from './BenchmarkLogger';

export interface HudSnapshot {
  state: HudState;
  pageKind: MoodlePageKind;
  summaryModalOpen: boolean;
  zones: readonly HudZone[];
  progressByZone: Map<ZoneId, number>;
  activeZoneId: ZoneId | null;
  lockedOptionIndex: number | null;
  navState: MoodleNavState;
  lastFrame: GazeFrame | null;
  faceLost: boolean;
  multiQuestionWarning: boolean;
}

/**
 * Pure 5-State Finite State Machine for Gaze-CBT HUD.
 * Driven exclusively by normalized GazeFrame payloads (live webcam or mock mouse).
 */
export class HudStateMachine {
  private state: HudState = 'CALIBRATING';
  private pageKind: MoodlePageKind = 'attempt';
  private config: HudConfig;
  private readonly dwell = new LeakyDwellController();
  private readonly filter = new OneEuroFilter2D();

  private lockStartedAtMs = 0;
  private cooldownStartedAtMs = 0;
  private lockedOptionIndex: number | null = null;
  private lastLowConfidenceAtMs: number | null = null;
  private faceLost = false;
  private lastFrame: GazeFrame | null = null;
  private activeZoneId: ZoneId | null = null;
  private progressByZone = new Map<ZoneId, number>();

  private cachedOptions: QuestionOption[] = [];
  private cachedNavState: MoodleNavState = {
    hasPrev: false,
    hasNext: false,
    isFinish: false,
    questionLabel: 'Question',
    answeredLabel: '',
    timeLeftLabel: '',
  };

  constructor(
    private readonly bridge: MoodleDomBridge,
    config: Partial<HudConfig> = {},
    private readonly logger?: BenchmarkLogger,
    private readonly sourceKind: 'webcam' | 'mock' = 'webcam',
    private readonly onFinalSubmit?: () => void,
  ) {
    this.config = { ...DEFAULT_HUD_CONFIG, ...config };
    this.pageKind = this.bridge.detectPageKind();
    this.refreshDomCache();
  }

  getState(): HudState {
    return this.state;
  }

  getConfig(): HudConfig {
    return { ...this.config };
  }

  updateConfig(patch: Partial<HudConfig>): void {
    this.config = { ...this.config, ...patch };
  }

  /**
   * Transitions CALIBRATING -> READING once pre-flight & 9-point calibration finish
   * (or when weights restore from sessionStorage).
   */
  completeCalibration(): void {
    this.pageKind = this.bridge.detectPageKind();
    this.bridge.setGazeFocusActive(true);
    this.refreshDomCache();
    this.dwell.reset();
    this.filter.reset();
    this.state = 'READING';
    if (this.pageKind === 'attempt') {
      this.logger?.startTrial(
        this.cachedNavState.questionLabel,
        this.config.answerDwellMs,
        this.sourceKind,
      );
    }
  }

  refreshDomCache(): void {
    this.pageKind = this.bridge.detectPageKind();
    if (this.pageKind === 'attempt') {
      this.cachedOptions = this.bridge.scrapeQuestionOptions();
      this.cachedNavState = this.bridge.getNavState();
    } else if (this.pageKind === 'summary') {
      this.cachedOptions = [];
      this.cachedNavState = {
        hasPrev: this.bridge.hasSummaryReturn(),
        hasNext: true,
        isFinish: true,
        questionLabel: 'Quiz Summary',
        answeredLabel: 'Review Before Submit',
        timeLeftLabel: '',
      };
    }
  }

  step(rawFrame: GazeFrame): HudSnapshot {
    const isHighConfidence =
      Number.isFinite(rawFrame.x) &&
      Number.isFinite(rawFrame.y) &&
      rawFrame.confidence >= this.config.minConfidence;

    if (!isHighConfidence) {
      if (this.lastLowConfidenceAtMs === null) {
        this.lastLowConfidenceAtMs = rawFrame.timestamp;
      } else if (rawFrame.timestamp - this.lastLowConfidenceAtMs >= 1000) {
        this.faceLost = true;
      }
    } else {
      this.lastLowConfidenceAtMs = null;
      this.faceLost = false;
    }

    const filteredCoords =
      this.config.enableOneEuroFilter && this.sourceKind === 'webcam'
        ? this.filter.filter(
            rawFrame.x,
            rawFrame.y,
            rawFrame.timestamp,
            rawFrame.confidence,
            this.config.minConfidence,
          )
        : { x: rawFrame.x, y: rawFrame.y };

    const frame: GazeFrame = {
      x: filteredCoords.x,
      y: filteredCoords.y,
      confidence: rawFrame.confidence,
      timestamp: rawFrame.timestamp,
    };
    this.lastFrame = frame;

    if (this.state === 'CALIBRATING') {
      return this.buildSnapshot([]);
    }

    if (this.state === 'ANSWER_ENTRY_LOCK') {
      if (frame.timestamp - this.lockStartedAtMs >= this.config.entryLockMs) {
        this.dwell.reset();
        this.state = 'ANSWER_OVERLAY';
      }
      return this.buildSnapshot(this.getActiveZones());
    }

    if (this.state === 'ACTION_COOLDOWN') {
      if (frame.timestamp - this.cooldownStartedAtMs >= this.config.cooldownMs) {
        this.lockedOptionIndex = null;
        this.dwell.reset();
        this.refreshDomCache();
        this.state = 'READING';
      }
      return this.buildSnapshot(this.getActiveZones());
    }

    // Periodically keep timer / nav / modal status fresh during READING.
    if (this.state === 'READING') {
      this.refreshDomCache();
    }

    const zones = this.getActiveZones();
    const result = this.dwell.step(frame, zones, this.config);
    this.activeZoneId = result.activeZoneId;
    this.progressByZone = result.progressByZone;

    if (result.completedZoneId !== null) {
      this.handleZoneCompleted(result.completedZoneId, frame.timestamp);
    }

    return this.buildSnapshot(this.getActiveZones());
  }

  private getActiveZones(): HudZone[] {
    if (this.pageKind === 'summary') {
      if (this.bridge.isSummaryModalOpen()) {
        return buildSummaryModalZones(this.config);
      }
      return buildSummaryReadingZones(this.config, this.bridge.hasSummaryReturn());
    }

    if (this.state === 'READING') {
      return buildReadingZones(this.cachedNavState, this.config);
    }

    if (
      this.state === 'ANSWER_ENTRY_LOCK' ||
      this.state === 'ANSWER_OVERLAY' ||
      this.state === 'ACTION_COOLDOWN'
    ) {
      return buildAnswerOverlayZones(this.cachedOptions, this.config);
    }

    return [];
  }

  private handleZoneCompleted(zoneId: ZoneId, timestampMs: number): void {
    this.dwell.reset();
    this.activeZoneId = null;
    this.progressByZone = new Map();

    if (this.pageKind === 'summary') {
      this.handleSummaryZoneCompleted(zoneId);
      return;
    }

    if (this.state === 'READING') {
      if (zoneId === 'PREV') {
        this.logger?.completeTrial();
        this.bridge.clickPrev();
      } else if (zoneId === 'NEXT') {
        this.logger?.completeTrial();
        this.bridge.clickNextOrFinish();
      } else if (zoneId === 'ANS') {
        this.refreshDomCache();
        this.lockStartedAtMs = timestampMs;
        this.state = 'ANSWER_ENTRY_LOCK';
      }
      return;
    }

    if (this.state === 'ANSWER_OVERLAY') {
      if (zoneId === 'CANCEL') {
        this.logger?.recordCancel();
        this.state = 'READING';
        return;
      }
      if (zoneId.startsWith('OPT_')) {
        const optionIndex = Number(zoneId.replace('OPT_', ''));
        if (Number.isInteger(optionIndex) && this.bridge.selectOptionByIndex(optionIndex)) {
          this.logger?.recordSelection(optionIndex);
          this.lockedOptionIndex = optionIndex;
          this.cooldownStartedAtMs = timestampMs;
          this.state = 'ACTION_COOLDOWN';
        } else {
          this.state = 'READING';
        }
      }
    }
  }

  private handleSummaryZoneCompleted(zoneId: ZoneId): void {
    if (zoneId === 'SUMMARY_RETURN') {
      this.bridge.clickSummaryReturn();
    } else if (zoneId === 'SUMMARY_SUBMIT') {
      this.bridge.clickSummarySubmitStep1();
    } else if (zoneId === 'MODAL_CANCEL') {
      this.bridge.clickSummaryModalCancel();
    } else if (zoneId === 'MODAL_CONFIRM') {
      this.onFinalSubmit?.();
      this.bridge.clickSummaryModalSave();
    }
  }

  private buildSnapshot(zones: readonly HudZone[]): HudSnapshot {
    return {
      state: this.state,
      pageKind: this.pageKind,
      summaryModalOpen: this.pageKind === 'summary' && this.bridge.isSummaryModalOpen(),
      zones,
      progressByZone: this.progressByZone,
      activeZoneId: this.activeZoneId,
      lockedOptionIndex: this.lockedOptionIndex,
      navState: this.cachedNavState,
      lastFrame: this.lastFrame,
      faceLost: this.faceLost,
      multiQuestionWarning:
        this.pageKind === 'attempt' && this.bridge.getQuestionCountOnPage() > 1,
    };
  }
}
