import type { TrialMetric } from './contracts';

const STORAGE_KEY = 'gaze_cbt_benchmark_trials_v1';

/**
 * Records structured trial metrics (completion speed, cancel count, option switches)
 * for Thursday empirical dwell benchmarking across 1500 ms, 2000 ms, and 3000 ms.
 */
export class BenchmarkLogger {
  private trials: TrialMetric[] = [];
  private activeTrial: TrialMetric | null = null;

  constructor(private readonly storage: Storage | null = safeSessionStorage()) {
    this.loadFromStorage();
  }

  startTrial(questionLabel: string, answerDwellMs: number, source: 'webcam' | 'mock'): void {
    if (this.activeTrial && this.activeTrial.completedAtMs === null) {
      return;
    }
    const now = performance.now();
    this.activeTrial = {
      trialIndex: this.trials.length + 1,
      questionLabel,
      answerDwellMs,
      startedAtMs: Math.round(now),
      completedAtMs: null,
      durationMs: null,
      cancelCount: 0,
      optionSwitchCount: 0,
      selectedOptionIndex: null,
      source,
    };
  }

  recordCancel(): void {
    if (!this.activeTrial) return;
    this.activeTrial.cancelCount += 1;
  }

  recordSelection(optionIndex: number): void {
    if (!this.activeTrial) return;
    if (
      this.activeTrial.selectedOptionIndex !== null &&
      this.activeTrial.selectedOptionIndex !== optionIndex
    ) {
      this.activeTrial.optionSwitchCount += 1;
    }
    this.activeTrial.selectedOptionIndex = optionIndex;
  }

  completeTrial(): void {
    if (!this.activeTrial) return;
    const now = Math.round(performance.now());
    this.activeTrial.completedAtMs = now;
    this.activeTrial.durationMs = Math.max(0, now - this.activeTrial.startedAtMs);
    this.trials.push(this.activeTrial);
    this.activeTrial = null;
    this.saveToStorage();
  }

  getTrials(): readonly TrialMetric[] {
    return this.trials;
  }

  clear(): void {
    this.trials = [];
    this.activeTrial = null;
    this.storage?.removeItem(STORAGE_KEY);
  }

  toJSON(): string {
    return JSON.stringify(this.trials, null, 2);
  }

  toCSV(): string {
    const header = [
      'trialIndex',
      'questionLabel',
      'answerDwellMs',
      'durationMs',
      'cancelCount',
      'optionSwitchCount',
      'selectedOptionIndex',
      'source',
    ].join(',');

    const rows = this.trials.map((t) =>
      [
        t.trialIndex,
        csvEscape(t.questionLabel),
        t.answerDwellMs,
        t.durationMs ?? '',
        t.cancelCount,
        t.optionSwitchCount,
        t.selectedOptionIndex ?? '',
        t.source,
      ].join(','),
    );
    return [header, ...rows].join('\n');
  }

  private loadFromStorage(): void {
    if (!this.storage) return;
    try {
      const raw = this.storage.getItem(STORAGE_KEY);
      if (!raw) return;
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed)) {
        this.trials = parsed;
      }
    } catch {
      this.trials = [];
    }
  }

  private saveToStorage(): void {
    if (!this.storage) return;
    try {
      this.storage.setItem(STORAGE_KEY, JSON.stringify(this.trials));
    } catch {
      // Ignore storage quota errors in restricted sandboxes.
    }
  }
}

function csvEscape(value: string): string {
  const escaped = value.replace(/"/g, '""');
  return `"${escaped}"`;
}

function safeSessionStorage(): Storage | null {
  try {
    return typeof sessionStorage !== 'undefined' ? sessionStorage : null;
  } catch {
    return null;
  }
}
