/**
 * Shared TypeScript contracts for Gaze-CBT (CV Engine <-> Canvas HUD <-> Moodle Bridge).
 */

export type HudState =
  | 'CALIBRATING'
  | 'READING'
  | 'ANSWER_ENTRY_LOCK'
  | 'ANSWER_OVERLAY'
  | 'ACTION_COOLDOWN';

export interface GazeFrame {
  /** Normalized viewport X in [0.0, 1.0]. */
  x: number;
  /** Normalized viewport Y in [0.0, 1.0]. */
  y: number;
  /** Face/iris tracking confidence in [0.0, 1.0]. */
  confidence: number;
  /** Monotonic timestamp from performance.now() in ms. */
  timestamp: number;
}

export interface HudConfig {
  /** Default: 3000 ms (PREV, NEXT/FINISH, ANS). */
  readingDwellMs: number;
  /** Default: 3000 ms (quick benchmark toggle: 1500 / 2000 / 3000 ms). */
  answerDwellMs: number;
  /** Default: 2000 ms (CANCEL strip in ANSWER_OVERLAY). */
  cancelDwellMs: number;
  /** Default: 500 ms (grace period preventing C/D pre-charging after ANS). */
  entryLockMs: number;
  /** Default: 800 ms (post-selection confirmation lock). */
  cooldownMs: number;
  /** Default: 1.5 (leaky-integrator decay multiplier). */
  decayMultiplier: number;
  /** Default: 0.5 (freeze/decay threshold on blink or face loss). */
  minConfidence: number;
  /** Smooth live webcam GazeFrame streams (bypassed automatically for mock mouse). */
  enableOneEuroFilter: boolean;
}

export const DEFAULT_HUD_CONFIG: HudConfig = {
  readingDwellMs: 3000,
  answerDwellMs: 3000,
  cancelDwellMs: 2000,
  entryLockMs: 500,
  cooldownMs: 800,
  decayMultiplier: 1.5,
  minConfidence: 0.5,
  enableOneEuroFilter: true,
};

export type MoodlePageKind = 'attempt' | 'summary' | 'unknown';

export type ZoneId =
  | 'PREV'
  | 'NEXT'
  | 'ANS'
  | 'CANCEL'
  | 'OPT_0'
  | 'OPT_1'
  | 'OPT_2'
  | 'OPT_3'
  | 'OPT_4'
  | 'SUMMARY_RETURN'
  | 'SUMMARY_SUBMIT'
  | 'MODAL_CANCEL'
  | 'MODAL_CONFIRM';

export interface NormalizedRect {
  x0: number;
  y0: number;
  x1: number;
  y1: number;
}

export interface HudZone {
  id: ZoneId;
  label: string;
  sublabel?: string;
  rect: NormalizedRect;
  dwellMs: number;
  variant: 'primary' | 'amber' | 'danger' | 'option' | 'neutral';
  checked?: boolean;
  disabled?: boolean;
}

export interface QuestionOption {
  index: number;
  letter: string;
  text: string;
  checked: boolean;
  inputEl: HTMLInputElement;
}

export interface MoodleNavState {
  hasPrev: boolean;
  hasNext: boolean;
  isFinish: boolean;
  questionLabel: string;
  answeredLabel: string;
  timeLeftLabel: string;
}

export interface TrialMetric {
  trialIndex: number;
  questionLabel: string;
  answerDwellMs: number;
  startedAtMs: number;
  completedAtMs: number | null;
  durationMs: number | null;
  cancelCount: number;
  optionSwitchCount: number;
  selectedOptionIndex: number | null;
  source: 'webcam' | 'mock';
}

export interface GazeProvider {
  readonly kind: 'webcam' | 'mock';
  start(onFrame: (frame: GazeFrame) => void): Promise<void>;
  stop(): void;
}
