import type { GazeFrame, GazeProvider } from './contracts';
import { clamp01 } from './OneEuroFilter';

export interface MockHarnessOptions {
  onDwellChange?: (answerDwellMs: number) => void;
  onToggleCursor?: (visible: boolean) => void;
  onExportCSV?: () => void;
  onExportJSON?: () => void;
  initialDwellMs?: number;
}

/**
 * Mouse-simulated GazeFrame provider for testing all 5 HUD states,
 * leaky-integrator dwell curves, and Moodle #responseform clicks without webcam hardware.
 */
export class MockMouseProvider implements GazeProvider {
  readonly kind = 'mock' as const;
  private rafId: number | null = null;
  private lastX = 0.5;
  private lastY = 0.5;
  private simulateFaceLoss = false;
  private toolbarEl: HTMLElement | null = null;
  private readonly handleMouseMove: (e: MouseEvent) => void;

  constructor(
    private readonly options: MockHarnessOptions = {},
    private readonly doc: Document = document,
  ) {
    this.handleMouseMove = (e: MouseEvent) => {
      const vw = Math.max(1, window.innerWidth);
      const vh = Math.max(1, window.innerHeight);
      this.lastX = clamp01(e.clientX / vw);
      this.lastY = clamp01(e.clientY / vh);
    };
  }

  async start(onFrame: (frame: GazeFrame) => void): Promise<void> {
    window.addEventListener('mousemove', this.handleMouseMove, { passive: true });
    this.mountToolbar();

    const tick = () => {
      onFrame({
        x: this.lastX,
        y: this.lastY,
        confidence: this.simulateFaceLoss ? 0.0 : 1.0,
        timestamp: performance.now(),
      });
      this.rafId = window.requestAnimationFrame(tick);
    };
    this.rafId = window.requestAnimationFrame(tick);
  }

  stop(): void {
    window.removeEventListener('mousemove', this.handleMouseMove);
    if (this.rafId !== null) {
      window.cancelAnimationFrame(this.rafId);
      this.rafId = null;
    }
    this.toolbarEl?.remove();
    this.toolbarEl = null;
  }

  private mountToolbar(): void {
    if (!this.doc.body || this.toolbarEl) return;
    const bar = this.doc.createElement('div');
    bar.id = 'gaze-cbt-mock-toolbar';
    bar.style.cssText = [
      'position:fixed',
      'bottom:10px',
      'right:10px',
      'z-index:99999',
      'background:rgba(15,23,42,0.92)',
      'color:#f8fafc',
      'padding:8px 10px',
      'border-radius:10px',
      'border:1px solid #475569',
      'font:600 12px/1.4 system-ui,sans-serif',
      'display:flex',
      'gap:6px',
      'align-items:center',
      'pointer-events:auto',
    ].join(';');

    const title = this.doc.createElement('span');
    title.textContent = 'Mock Gaze:';
    bar.appendChild(title);

    for (const ms of [1500, 2000, 3000]) {
      const btn = this.makeBtn(`${ms}ms`, () => this.options.onDwellChange?.(ms));
      if (this.options.initialDwellMs === ms) {
        btn.style.background = '#2563eb';
      }
      bar.appendChild(btn);
    }

    const lossBtn = this.makeBtn('Face-Loss: OFF', () => {
      this.simulateFaceLoss = !this.simulateFaceLoss;
      lossBtn.textContent = `Face-Loss: ${this.simulateFaceLoss ? 'ON' : 'OFF'}`;
      lossBtn.style.background = this.simulateFaceLoss ? '#dc2626' : '#334155';
    });
    bar.appendChild(lossBtn);

    let cursorVisible = true;
    this.options.onToggleCursor?.(true);
    const cursorBtn = this.makeBtn('Reticle: ON', () => {
      cursorVisible = !cursorVisible;
      cursorBtn.textContent = `Reticle: ${cursorVisible ? 'ON' : 'OFF'}`;
      this.options.onToggleCursor?.(cursorVisible);
    });
    bar.appendChild(cursorBtn);

    bar.appendChild(this.makeBtn('CSV', () => this.options.onExportCSV?.()));
    bar.appendChild(this.makeBtn('JSON', () => this.options.onExportJSON?.()));

    this.doc.body.appendChild(bar);
    this.toolbarEl = bar;
  }

  private makeBtn(label: string, onClick: () => void): HTMLButtonElement {
    const btn = this.doc.createElement('button');
    btn.type = 'button';
    btn.textContent = label;
    btn.style.cssText = [
      'background:#334155',
      'color:#f8fafc',
      'border:1px solid #64748b',
      'border-radius:6px',
      'padding:4px 8px',
      'cursor:pointer',
      'font:600 11px system-ui,sans-serif',
    ].join(';');
    btn.addEventListener('click', onClick);
    return btn;
  }
}
