import { BenchmarkLogger } from './BenchmarkLogger';
import { CanvasHudRenderer } from './CanvasHudRenderer';
import { DEFAULT_HUD_CONFIG, type GazeProvider, type HudConfig } from './contracts';
import { HudStateMachine } from './HudStateMachine';
import { MockMouseProvider } from './MockMouseProvider';
import { BrowserMoodleDomBridge } from './MoodleDomBridge';
import { RealEyeGazeProvider } from './RealEyeGazeProvider';

export interface GazeCbtBootConfig {
  enabled?: boolean;
  mockMode?: boolean;
  localAssetBaseUrl?: string;
  hudConfig?: Partial<HudConfig>;
}

interface StoredAttemptMode {
  enabled: boolean;
  mockMode: boolean;
  answerDwellMs?: number;
}

declare global {
  interface Window {
    GAZE_CBT_CONFIG?: GazeCbtBootConfig;
    GazeCBT?: {
      boot: typeof bootGazeCbt;
    };
  }
}

function readStoredMode(attemptId: string): StoredAttemptMode | null {
  try {
    const raw = sessionStorage.getItem(`gaze_cbt_mode_${attemptId}`);
    return raw ? (JSON.parse(raw) as StoredAttemptMode) : null;
  } catch {
    return null;
  }
}

function saveStoredMode(attemptId: string, mode: StoredAttemptMode): void {
  try {
    sessionStorage.setItem(`gaze_cbt_mode_${attemptId}`, JSON.stringify(mode));
  } catch {
    // Ignore storage errors.
  }
}

let activeCleanup: (() => void) | null = null;
let isBooting = false;

export async function bootGazeCbt(bootConfig: GazeCbtBootConfig = {}): Promise<() => void> {
  if (activeCleanup) {
    return activeCleanup;
  }
  if (isBooting) {
    return () => {};
  }
  isBooting = true;

  try {
    const params = new URLSearchParams(window.location.search);
    const hasMockParam = params.has('gaze_mock');
    const hasGazeParam = params.has('gaze');
    const queryMock = params.get('gaze_mock') === '1';
    const queryEnabled = params.get('gaze') === '1' || queryMock;
    const queryDwell = Number(params.get('dwell'));

    const bridge = new BrowserMoodleDomBridge(document);
    const pageKind = bridge.detectPageKind();
    const attemptId = bridge.getAttemptId();
    const storedMode = readStoredMode(attemptId);

    const isMock = hasMockParam
      ? queryMock
      : (bootConfig.mockMode ?? storedMode?.mockMode ?? false);
    const isEnabled = hasGazeParam || hasMockParam
      ? queryEnabled
      : (bootConfig.enabled ?? (Boolean(window.GAZE_CBT_CONFIG?.enabled) || Boolean(storedMode?.enabled)));

    if (!isEnabled || pageKind === 'unknown') {
      isBooting = false;
      return () => {};
    }

    const resolvedDwellMs =
      Number.isFinite(queryDwell) && queryDwell >= 500
        ? queryDwell
        : (bootConfig.hudConfig?.answerDwellMs ?? storedMode?.answerDwellMs);

    saveStoredMode(attemptId, {
      enabled: isEnabled,
      mockMode: isMock,
      answerDwellMs: resolvedDwellMs,
    });

    const hudConfig: HudConfig = {
      ...DEFAULT_HUD_CONFIG,
      ...bootConfig.hudConfig,
      ...(resolvedDwellMs ? { answerDwellMs: resolvedDwellMs } : {}),
    };

    console.info('[Gaze-CBT] Booting HUD:', { pageKind, attemptId, isMock, answerDwellMs: hudConfig.answerDwellMs });

    const logger = new BenchmarkLogger();
    const renderer = new CanvasHudRenderer(document);
    renderer.mount();

    let provider: GazeProvider;

    const fsm = new HudStateMachine(
      bridge,
      hudConfig,
      logger,
      isMock ? 'mock' : 'webcam',
      () => {
        try {
          sessionStorage.removeItem(`gaze_cbt_cal_${attemptId}`);
          sessionStorage.removeItem(`gaze_cbt_mode_${attemptId}`);
        } catch {
          // Ignore storage errors.
        }
      },
    );

    if (isMock) {
      provider = new MockMouseProvider({
        initialDwellMs: hudConfig.answerDwellMs,
        onDwellChange: (ms) => {
          fsm.updateConfig({ answerDwellMs: ms });
          saveStoredMode(attemptId, { enabled: true, mockMode: true, answerDwellMs: ms });
        },
        onToggleCursor: (visible) => renderer.setShowGazeCursor(visible),
        onExportCSV: () => downloadText(`gaze-cbt-trials-${Date.now()}.csv`, logger.toCSV(), 'text/csv'),
        onExportJSON: () => downloadText(`gaze-cbt-trials-${Date.now()}.json`, logger.toJSON(), 'application/json'),
      });
      fsm.completeCalibration();
    } else {
      provider = new RealEyeGazeProvider({
        attemptId,
        localAssetBaseUrl: bootConfig.localAssetBaseUrl,
        onCalibrationComplete: () => fsm.completeCalibration(),
      });
    }

    await provider.start((frame) => {
      const snapshot = fsm.step(frame);
      renderer.render(snapshot);
    });

    activeCleanup = () => {
      provider.stop();
      renderer.unmount();
      bridge.setGazeFocusActive(false);
      activeCleanup = null;
    };
    isBooting = false;
    return activeCleanup;
  } catch (err) {
    isBooting = false;
    console.error('[Gaze-CBT] Failed to boot:', err);
    throw err;
  }
}

function downloadText(filename: string, content: string, mimeType: string): void {
  const blob = new Blob([content], { type: mimeType });
  const url = URL.createObjectURL(blob);
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  a.click();
  URL.revokeObjectURL(url);
}

if (typeof window !== 'undefined') {
  window.GazeCBT = { boot: bootGazeCbt };
  const autoStart = () => {
    const params = new URLSearchParams(window.location.search);
    const bridge = new BrowserMoodleDomBridge(document);
    const attemptId = bridge.getAttemptId();
    const stored = readStoredMode(attemptId);
    if (
      window.GAZE_CBT_CONFIG?.enabled ||
      params.get('gaze') === '1' ||
      params.get('gaze_mock') === '1' ||
      stored?.enabled
    ) {
      void bootGazeCbt(window.GAZE_CBT_CONFIG);
    }
  };
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', autoStart);
  } else {
    autoStart();
  }
}

