import type { HudConfig, HudZone, MoodleNavState, QuestionOption, ZoneId } from './contracts';

const OPTION_ZONE_IDS: readonly ZoneId[] = ['OPT_0', 'OPT_1', 'OPT_2', 'OPT_3', 'OPT_4'];

/**
 * Builds the READING Mode zones around the 52% vertical Dead Zone (y: 0.22-0.74).
 */
export function buildReadingZones(nav: MoodleNavState, config: HudConfig): HudZone[] {
  const zones: HudZone[] = [];

  if (nav.hasPrev) {
    zones.push({
      id: 'PREV',
      label: 'PREV',
      rect: { x0: 0.0, y0: 0.0, x1: 0.3, y1: 0.22 },
      dwellMs: config.readingDwellMs,
      variant: 'primary',
    });
  }

  if (nav.hasNext) {
    zones.push({
      id: 'NEXT',
      label: nav.isFinish ? 'FINISH' : 'NEXT',
      rect: { x0: 0.7, y0: 0.0, x1: 1.0, y1: 0.22 },
      dwellMs: config.readingDwellMs,
      variant: nav.isFinish ? 'amber' : 'primary',
    });
  }

  zones.push({
    id: 'ANS',
    label: 'ANS',
    rect: { x0: 0.25, y0: 0.74, x1: 0.75, y1: 1.0 },
    dwellMs: config.readingDwellMs,
    variant: 'primary',
  });

  return zones;
}

/**
 * Builds the ANSWER_OVERLAY zones:
 * - Top-center CANCEL strip (x: 0.35-0.65, y: 0.00-0.12)
 * - 2 options (True/False): 2 half-screen columns with 6% center vertical gutter
 * - 4 options (A-D): 4 quadrants with 6% horizontal and 4% vertical neutral gutters
 * - 3 or 5 options: graceful 3-top + 2-bottom fallback with neutral gutters
 */
export function buildAnswerOverlayZones(
  options: readonly QuestionOption[],
  config: HudConfig,
): HudZone[] {
  const zones: HudZone[] = [
    {
      id: 'CANCEL',
      label: 'CANCEL',
      rect: { x0: 0.35, y0: 0.0, x1: 0.65, y1: 0.12 },
      dwellMs: config.cancelDwellMs,
      variant: 'danger',
    },
  ];

  const count = options.length;
  if (count === 2) {
    const rects = [
      { x0: 0.0, y0: 0.12, x1: 0.47, y1: 1.0 },
      { x0: 0.53, y0: 0.12, x1: 1.0, y1: 1.0 },
    ];
    options.forEach((opt, i) => {
      const rect = rects[i];
      const zoneId = OPTION_ZONE_IDS[i];
      if (!rect || !zoneId) return;
      zones.push({
        id: zoneId,
        label: opt.letter,
        sublabel: opt.text,
        rect,
        dwellMs: config.answerDwellMs,
        variant: 'option',
        checked: opt.checked,
      });
    });
    return zones;
  }

  if (count <= 4) {
    const rects = [
      { x0: 0.0, y0: 0.12, x1: 0.47, y1: 0.53 }, // A Top-Left
      { x0: 0.53, y0: 0.12, x1: 1.0, y1: 0.53 }, // B Top-Right
      { x0: 0.0, y0: 0.57, x1: 0.47, y1: 1.0 }, // C Bottom-Left
      { x0: 0.53, y0: 0.57, x1: 1.0, y1: 1.0 }, // D Bottom-Right
    ];
    options.forEach((opt, i) => {
      const rect = rects[i];
      const zoneId = OPTION_ZONE_IDS[i];
      if (!rect || !zoneId) return;
      zones.push({
        id: zoneId,
        label: opt.letter,
        sublabel: opt.text,
        rect,
        dwellMs: config.answerDwellMs,
        variant: 'option',
        checked: opt.checked,
      });
    });
    return zones;
  }

  // Graceful fallback for 5-option MCQs (A-E): top row 3, bottom row 2
  const fallbackRects = [
    { x0: 0.0, y0: 0.12, x1: 0.31, y1: 0.53 },
    { x0: 0.345, y0: 0.12, x1: 0.655, y1: 0.53 },
    { x0: 0.69, y0: 0.12, x1: 1.0, y1: 0.53 },
    { x0: 0.0, y0: 0.57, x1: 0.47, y1: 1.0 },
    { x0: 0.53, y0: 0.57, x1: 1.0, y1: 1.0 },
  ];
  options.slice(0, 5).forEach((opt, i) => {
    const rect = fallbackRects[i];
    const zoneId = OPTION_ZONE_IDS[i];
    if (!rect || !zoneId) return;
    zones.push({
      id: zoneId,
      label: opt.letter,
      sublabel: opt.text,
      rect,
      dwellMs: config.answerDwellMs,
      variant: 'option',
      checked: opt.checked,
    });
  });
  return zones;
}

/**
 * Builds summary.php Stage 1 zones (framing native summary table in center Dead Zone).
 */
export function buildSummaryReadingZones(config: HudConfig, hasReturn: boolean): HudZone[] {
  const zones: HudZone[] = [];
  if (hasReturn) {
    zones.push({
      id: 'SUMMARY_RETURN',
      label: 'RETURN',
      sublabel: 'Kembali ke Ujian',
      rect: { x0: 0.0, y0: 0.0, x1: 0.35, y1: 0.22 },
      dwellMs: config.readingDwellMs,
      variant: 'primary',
    });
  }
  zones.push({
    id: 'SUMMARY_SUBMIT',
    label: 'SUBMIT ALL',
    sublabel: 'Kumpulkan Jawaban',
    rect: { x0: 0.65, y0: 0.0, x1: 1.0, y1: 0.22 },
    dwellMs: config.readingDwellMs,
    variant: 'amber',
  });
  return zones;
}

/**
 * Builds summary.php Stage 2 Bootstrap confirmation modal overlay zones.
 */
export function buildSummaryModalZones(config: HudConfig): HudZone[] {
  return [
    {
      id: 'MODAL_CANCEL',
      label: 'BATAL',
      sublabel: 'Tutup Konfirmasi',
      rect: { x0: 0.08, y0: 0.62, x1: 0.46, y1: 0.9 },
      dwellMs: config.cancelDwellMs,
      variant: 'danger',
    },
    {
      id: 'MODAL_CONFIRM',
      label: 'KIRIM FINAL',
      sublabel: 'Submit All and Finish',
      rect: { x0: 0.54, y0: 0.62, x1: 0.92, y1: 0.9 },
      dwellMs: config.readingDwellMs,
      variant: 'amber',
    },
  ];
}
