import type { MoodleNavState, MoodlePageKind, QuestionOption } from './contracts';

const LETTERS = ['A', 'B', 'C', 'D', 'E'] as const;

export interface MoodleDomBridge {
  detectPageKind(): MoodlePageKind;
  getAttemptId(): string;
  getQuestionCountOnPage(): number;
  scrapeQuestionOptions(): QuestionOption[];
  selectOptionByIndex(index: number): boolean;
  getNavState(): MoodleNavState;
  clickPrev(): boolean;
  clickNextOrFinish(): boolean;
  hasSummaryReturn(): boolean;
  clickSummaryReturn(): boolean;
  clickSummarySubmitStep1(): boolean;
  isSummaryModalOpen(): boolean;
  clickSummaryModalSave(): boolean;
  clickSummaryModalCancel(): boolean;
  setGazeFocusActive(active: boolean): void;
}

/**
 * Safe Moodle 4.x DOM adapter.
 * Always triggers native DOM .click() on #responseform controls so Moodle persists
 * selections via POST rather than discarding state with window.location redirects.
 */
export class BrowserMoodleDomBridge implements MoodleDomBridge {
  constructor(private readonly doc: Document = document) {}

  detectPageKind(): MoodlePageKind {
    const bodyId = this.doc.body?.id ?? '';
    const path = this.doc.location?.pathname ?? '';
    if (bodyId === 'page-mod-quiz-summary' || path.includes('summary.php')) {
      return 'summary';
    }
    if (bodyId === 'page-mod-quiz-attempt' || path.includes('attempt.php') || this.doc.querySelector('#responseform')) {
      return 'attempt';
    }
    return 'unknown';
  }

  getAttemptId(): string {
    const search = this.doc.location?.search ?? '';
    const fromQuery = new URLSearchParams(search).get('attempt');
    if (fromQuery) return fromQuery;
    const hidden = this.doc.querySelector<HTMLInputElement>('#responseform input[name="attempt"], input[name="attempt"]');
    return hidden?.value || 'local-attempt';
  }

  getQuestionCountOnPage(): number {
    return this.doc.querySelectorAll('#responseform .que').length;
  }

  scrapeQuestionOptions(): QuestionOption[] {
    const firstQue = this.doc.querySelector('#responseform .que');
    if (!firstQue) return [];

    const radios = Array.from(
      firstQue.querySelectorAll<HTMLInputElement>('.answer input[type="radio"]'),
    ).filter((el) => !el.disabled && (el.offsetParent !== null || isElementPotentiallyVisible(el)));

    return radios.map((inputEl, idx) => {
      const labelText = extractOptionLabelText(inputEl, idx);
      return {
        index: idx,
        letter: LETTERS[idx] ?? String(idx + 1),
        text: labelText,
        checked: inputEl.checked,
        inputEl,
      };
    });
  }

  selectOptionByIndex(index: number): boolean {
    const options = this.scrapeQuestionOptions();
    const target = options[index];
    if (!target) return false;
    const wasChecked = target.inputEl.checked;
    target.inputEl.click();
    if (wasChecked) {
      const EventCtor = target.inputEl.ownerDocument.defaultView?.Event ?? Event;
      target.inputEl.dispatchEvent(new EventCtor('change', { bubbles: true }));
    }
    return true;
  }

  getNavState(): MoodleNavState {
    const prevEl = this.queryPrevButton();
    const nextEl = this.queryNextButton();

    const nextText = readButtonText(nextEl);
    const isFinish = /finish\s+attempt/i.test(nextText);

    const qnButtons = Array.from(this.doc.querySelectorAll('.drawer-right .qnbutton, .qn_buttons .qnbutton'));
    const total = qnButtons.length;
    const currentIdx = qnButtons.findIndex((btn) => btn.classList.contains('thispage'));
    const answeredCount = qnButtons.filter((btn) => btn.classList.contains('answersaved')).length;

    const questionLabel =
      total > 0 && currentIdx >= 0
        ? `Question ${currentIdx + 1} of ${total}`
        : this.scrapeFallbackQuestionHeading();

    const answeredLabel = total > 0 ? `${answeredCount} Answered` : '';
    const rawTime = this.doc.querySelector('#quiz-time-left')?.textContent?.trim() ?? '';
    const timeLeftLabel = rawTime ? `Time left ${rawTime}` : '';

    return {
      hasPrev: Boolean(prevEl && !prevEl.disabled),
      hasNext: Boolean(nextEl && !nextEl.disabled),
      isFinish,
      questionLabel,
      answeredLabel,
      timeLeftLabel,
    };
  }

  clickPrev(): boolean {
    const btn = this.queryPrevButton();
    if (!btn || btn.disabled) return false;
    btn.click();
    return true;
  }

  clickNextOrFinish(): boolean {
    const btn = this.queryNextButton();
    if (!btn || btn.disabled) return false;
    btn.click();
    return true;
  }

  hasSummaryReturn(): boolean {
    return Boolean(this.querySummaryReturnButton());
  }

  clickSummaryReturn(): boolean {
    const btn = this.querySummaryReturnButton();
    if (!btn) return false;
    btn.click();
    return true;
  }

  clickSummarySubmitStep1(): boolean {
    const btn = this.doc.querySelector<HTMLButtonElement>(
      '#frm-finishattempt button[type="submit"], .btn-finishattempt button[type="submit"], button.btn-primary[type="submit"]',
    );
    if (!btn || btn.disabled) return false;
    btn.click();
    return true;
  }

  isSummaryModalOpen(): boolean {
    const modal = this.doc.querySelector<HTMLElement>('[data-region="modal"]');
    if (!modal) return false;
    const style = modal.style?.display;
    const ariaHidden = modal.getAttribute('aria-hidden');
    return style !== 'none' && ariaHidden !== 'true';
  }

  clickSummaryModalSave(): boolean {
    const btn = this.doc.querySelector<HTMLButtonElement>(
      '[data-region="modal"] button[data-action="save"], .modal.show [data-action="save"], .moodle-dialogue-confirm input[value*="Submit"]',
    );
    if (!btn || btn.disabled) return false;
    btn.click();
    return true;
  }

  clickSummaryModalCancel(): boolean {
    const btn = this.doc.querySelector<HTMLButtonElement>(
      '[data-region="modal"] button[data-action="cancel"], [data-region="modal"] button.btn-secondary, [data-region="modal"] .close, [data-region="modal"] .btn-close',
    );
    if (!btn) return false;
    btn.click();
    return true;
  }

  setGazeFocusActive(active: boolean): void {
    if (!this.doc.body) return;
    if (active) {
      this.doc.body.classList.add('gaze-cbt-active');
    } else {
      this.doc.body.classList.remove('gaze-cbt-active');
    }
  }

  private queryPrevButton(): HTMLButtonElement | HTMLInputElement | null {
    return this.doc.querySelector<HTMLButtonElement | HTMLInputElement>(
      '#responseform input[name="previous"], #mod_quiz-prev-nav',
    );
  }

  private queryNextButton(): HTMLButtonElement | HTMLInputElement | null {
    return this.doc.querySelector<HTMLButtonElement | HTMLInputElement>(
      '#responseform input[name="next"], #mod_quiz-next-nav',
    );
  }

  private querySummaryReturnButton(): HTMLElement | null {
    const formReturn = this.doc.querySelector<HTMLElement>(
      '.submitbtns form[action*="attempt.php"] button[type="submit"], form[action*="attempt.php"] button[type="submit"], .submitbtns button.btn-secondary[type="submit"]',
    );
    if (formReturn) return formReturn;
    return this.doc.querySelector<HTMLElement>('a[href*="attempt.php"]');
  }

  private scrapeFallbackQuestionHeading(): string {
    const heading = this.doc.querySelector('#responseform .que .info .qno')?.textContent?.trim();
    return heading ? `Question ${heading}` : 'Question';
  }
}

function isElementPotentiallyVisible(el: HTMLInputElement): boolean {
  return el.type !== 'hidden' && el.style.display !== 'none';
}

function readButtonText(el: HTMLButtonElement | HTMLInputElement | null): string {
  if (!el) return '';
  if ('value' in el && typeof el.value === 'string' && el.value.length > 0) {
    return el.value.trim();
  }
  return el.textContent?.trim() ?? '';
}

function extractOptionLabelText(inputEl: HTMLInputElement, index: number): string {
  const row = inputEl.closest('.r0, .r1, .form-check, .d-flex, div') ?? inputEl.parentElement;
  const flexLabel =
    row?.querySelector<HTMLElement>('.flex-fill, .d-flex .ms-1, label') ??
    inputEl.labels?.[0] ??
    row;

  const raw = (flexLabel?.textContent ?? '').replace(/\s+/g, ' ').trim();
  // Strip redundant leading "a. " / "A. " prefix so tile displays oversized A + clean text.
  const cleaned = raw.replace(/^[a-eA-E][.)]\s+/, '').trim();
  return cleaned || `Option ${LETTERS[index] ?? index + 1}`;
}
